{
  "name": "一维数据查看器",
  "name_en": "1D Data Viewer",
  "manufacturer": "",
  "description": "用于实验数据可视化的非物理软件组件，可在图形界面中显示一维 DataWithAxis 数据，并提供十字光标、ROI、线剖面、标签和状态文本等交互功能。",
  "description_en": "A non-physical software component for experimental data visualization. It displays 1D DataWithAxis data in a GUI and provides interactive features such as crosshairs, ROIs, lineouts, labels, and status text.",
  "tag_hints": [
    "1D data visualization",
    "GUI plot viewer",
    "crosshair interaction",
    "ROI selection",
    "lineout processing",
    "PyMoDAQ GUI",
    "experimental data display"
  ],
  "actions": [
    {
      "action_name": "auto-update_colors",
      "description": "更新绘图颜色",
      "description_en": "update plot colors"
    },
    {
      "action_name": "auto-move_roi_target",
      "description": "移动指定的 ROI 目标位置",
      "description_en": "move the specified ROI target position"
    },
    {
      "action_name": "auto-set_crosshair_position",
      "description": "设置十字光标位置",
      "description_en": "set the crosshair position"
    },
    {
      "action_name": "auto-add_plot_item",
      "description": "添加绘图项",
      "description_en": "add a plot item"
    },
    {
      "action_name": "auto-process_crosshair_lineouts",
      "description": "处理十字光标线剖面数据",
      "description_en": "process crosshair lineout data"
    },
    {
      "action_name": "auto-process_roi_lineouts",
      "description": "处理 ROI 线剖面数据",
      "description_en": "process ROI lineout data"
    },
    {
      "action_name": "auto-prepare_connect_ui",
      "description": "准备界面连接",
      "description_en": "prepare UI connections"
    },
    {
      "action_name": "auto-selected_region_changed",
      "description": "处理选区变化",
      "description_en": "handle selected region changes"
    },
    {
      "action_name": "auto-double_clicked",
      "description": "处理查看器中的双击事件",
      "description_en": "handle double-click events in the viewer"
    },
    {
      "action_name": "auto-roi_changed",
      "description": "处理 ROI 变化",
      "description_en": "handle ROI changes"
    },
    {
      "action_name": "auto-crosshair_changed",
      "description": "处理十字光标变化",
      "description_en": "handle crosshair changes"
    },
    {
      "action_name": "auto-activate_roi",
      "description": "启用或禁用 ROI",
      "description_en": "activate or deactivate ROI"
    },
    {
      "action_name": "auto-labels",
      "description": "获取/设置标签",
      "description_en": "get/set labels"
    },
    {
      "action_name": "auto-update_status",
      "description": "更新状态文本",
      "description_en": "update status text"
    }
  ]
}

